fakes.git:
#!/bin/sh
# git diff --no-index --no-color -- <a> <b>
a="$5"
b="$6"
case "$a$b" in
  *gitfail*) printf 'fatal: fake git refuses\n' >&2; exit 128 ;;
  *nodiff*) exit 0 ;;
esac
printf -- '--- %s\n+++ %s\n@@ -1 +1 @@\n-old\n+new\n' "$a" "$b"
exit 1

